/// C bindings of this crate's headers (generated by build.rs), re-exported with those it builds on.
#[allow(
    non_camel_case_types,
    non_upper_case_globals,
    non_snake_case,
    dead_code,
    clippy::all
)]
mod sys {
    pub use rsf_game_sys::*;
    include!(concat!(env!("OUT_DIR"), "/sys.rs"));
}

/// Ends the fixture process at the first failed condition, naming the file and line.
macro_rules! check {
    ($condition:expr) => {
        if !$condition {
            eprintln!(
                "check failed at {}:{}: {}",
                file!(),
                line!(),
                stringify!($condition)
            );
            std::process::exit(1);
        }
    };
}

